{"command":"cat package.json; mkdir -p src; cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>', '+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.']
const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
  }
}

const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isLetter = (c) => c !== undefined && /^[A-Za-z]$/.test(c)
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdPart = (c) => isIdStart(c) || isDigit(c)

function scan(text) {
  const s = Array.from(text)
  const n = s.length
  const tokens = []
  let i = 0, line = 1, col = 1

  const adv = () => {
    const c = s[i++]
    if (c === '\n') { line++; col = 1 }
    else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
    return c
  }
  const advN = (k) => { while (k-- > 0) adv() }

  while (i < n) {
    const c = s[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { adv(); continue }
    if (c === '/' && s[i + 1] === '/') {
      while (i < n && s[i] !== '\n') adv()
      continue
    }
    if (c === '/' && s[i + 1] === '*') {
      const l0 = line, c0 = col
      let depth = 0
      do {
        if (i >= n) throw new ScanError(l0, c0, 'unterminated block comment')
        if (s[i] === '/' && s[i + 1] === '*') { depth++; advN(2) }
        else if (s[i] === '*' && s[i + 1] === '/') { depth--; advN(2) }
        else adv()
      } while (depth > 0)
      continue
    }
    const l0 = line, c0 = col
    if (c === 'r' && s[i + 1] === '"') {
      let j = i + 2
      while (j < n && s[j] !== '"') j++
      if (j >= n) throw new ScanError(l0, c0, 'unterminated string')
      const value = s.slice(i + 2, j).join('')
      advN(j + 1 - i)
      tokens.push({ line: l0, col: c0, kind: 'rawstring', body: JSON.stringify(value) })
      continue
    }
    if (isIdStart(c)) {
      let j = i
      while (isIdPart(s[j])) j++
      const word = s.slice(i, j).join('')
      advN(j - i)
      tokens.push({ line: l0, col: c0, kind: KEYWORDS.has(word) ? 'keyword' : 'ident', body: word })
      continue
    }
    if (isDigit(c)) {
      let j = i
      // run of digits accepted by pred, with single underscores between digits
      const run = (pred) => {
        if (!pred(s[j])) return false
        while (true) {
          if (pred(s[j])) j++
          else if (s[j] === '_' && pred(s[j + 1]) && pred(s[j - 1])) j++
          else break
        }
        return true
      }
      const p = (s[i + 1] || '').toLowerCase()
      if (c === '0' && (p === 'x' || p === 'b' || p === 'o')) {
        j = i + 2
        const pred = p === 'x' ? isHex : p === 'b' ? (d) => d === '0' || d === '1' : (d) => d !== undefined && d >= '0' && d <= '7'
        run(pred)
      } else {
        run(isDigit)
        if (s[j] === '.' && isDigit(s[j + 1])) { j++; run(isDigit) }
        if (s[j] === 'e' || s[j] === 'E') {
          if (isDigit(s[j + 1])) { j++; run(isDigit) }
          else if ((s[j + 1] === '+' || s[j + 1] === '-') && isDigit(s[j + 2])) { j += 2; run(isDigit) }
        }
      }
      const prefixOnly = c === '0' && (p === 'x' || p === 'b' || p === 'o') && j === i + 2
      let bad = prefixOnly
      while (isIdPart(s[j])) { j++; bad = true }
      const body = s.slice(i, j).join('')
      if (bad) throw new ScanError(l0, c0, `invalid number ${body}`)
      advN(j - i)
      tokens.push({ line: l0, col: c0, kind: 'number', body })
      continue
    }
    if (c === '"') {
      adv()
      let value = ''
      while (true) {
        if (i >= n) throw new ScanError(l0, c0, 'unterminated string')
        const d = s[i]
        if (d === '"') { adv(); break }
        if (d === '\n') throw new ScanError(line, col, 'newline in string')
        if (d !== '\\') { value += adv(); continue }
        const bl = line, bc = col
        adv()
        if (i >= n) throw new ScanError(l0, c0, 'unterminated string')
        const e = s[i]
        const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', '0': '\0' }
        if (e in simple) { adv(); value += simple[e]; continue }
        if (e === 'x') {
          if (isHex(s[i + 1]) && isHex(s[i + 2])) {
            value += String.fromCodePoint(parseInt(s[i + 1] + s[i + 2], 16))
            advN(3)
            continue
          }
        } else if (e === 'u' && s[i + 1] === '{') {
          let j = i + 2
          while (isHex(s[j])) j++
          if (j > i + 2 && s[j] === '}') {
            const v = parseInt(s.slice(i + 2, j).join(''), 16)
            if (v <= 0x10ffff) {
              value += String.fromCodePoint(v)
              advN(j + 1 - i)
              continue
            }
          }
        }
        throw new ScanError(bl, bc, `invalid escape \\${e}`)
      }
      tokens.push({ line: l0, col: c0, kind: 'string', body: JSON.stringify(value) })
      continue
    }
    const two = c + (s[i + 1] ?? '')
    const pm = PUNCT.find((x) => x === two) ?? PUNCT.find((x) => x === c)
    if (pm) {
      advN(pm.length)
      tokens.push({ line: l0, col: c0, kind: 'punct', body: pm })
      continue
    }
    throw new ScanError(l0, c0, `unexpected character ${c}`)
  }
  return tokens
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}
const input = readFileSync(0, 'utf8')
let tokens
try {
  tokens = scan(input)
} catch (e) {
  if (!(e instanceof ScanError)) throw e
  process.stderr.write(`error: ${e.line}:${e.col}: ${e.message}\n`)
  process.exit(2)
}
let out = ''
if (args[0] === 'tokens') {
  for (const t of tokens) out += `${t.line}:${t.col} ${t.kind} ${t.body}\n`
} else {
  for (const k of KINDS) out += `${k} ${tokens.filter((t) => t.kind === k).length}\n`
  out += `total ${tokens.length}\n`
}
process.stdout.write(out)
EOF
