import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

const NAME = /^[A-Za-z0-9_./:-]+$/
const INT = /^(0|[1-9][0-9]*)$/

class Fail extends Error {}

function parse(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let lastTick = null
  let seenEvent = false
  const int = (v, field, least) => {
    if (!INT.test(v) || BigInt(v) < BigInt(least)) throw new Fail(`${field} must be an integer of at least ${least}`)
    return BigInt(v)
  }
  const declOk = () => { if (seenEvent) throw new Fail('declarations must come before the first event') }
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const t = line.split(/\s+/)
    try {
      switch (t[0]) {
        case 'bucket': {
          if (t.length !== 5) throw new Fail('expected bucket <name> <capacity> <refill> <per>')
          declOk()
          if (!NAME.test(t[1])) throw new Fail(`invalid policy name ${t[1]}`)
          const capacity = int(t[2], 'capacity', 1)
          const refill = int(t[3], 'refill', 0)
          const per = int(t[4], 'per', 1)
          if (policies.has(t[1])) throw new Fail(`policy ${t[1]} is declared twice`)
          policies.set(t[1], { name: t[1], kind: 'bucket', capacity, refill, per })
          break
        }
        case 'window': {
          if (t.length !== 4) throw new Fail('expected window <name> <limit> <span>')
          declOk()
          if (!NAME.test(t[1])) throw new Fail(`invalid policy name ${t[1]}`)
          const limit = int(t[2], 'limit', 0)
          const span = int(t[3], 'span', 1)
          if (policies.has(t[1])) throw new Fail(`policy ${t[1]} is declared twice`)
          policies.set(t[1], { name: t[1], kind: 'window', limit, span })
          break
        }
        case 'route': {
          if (t.length < 3) throw new Fail('expected route <prefix> <policy>...')
          declOk()
          if (!NAME.test(t[1])) throw new Fail(`invalid route prefix ${t[1]}`)
          if (routes.has(t[1])) throw new Fail(`prefix ${t[1]} is routed twice`)
          for (const p of t.slice(2)) if (!policies.has(p)) throw new Fail(`unknown policy ${p}`)
          routes.set(t[1], t.slice(2).map((p) => policies.get(p)))
          break
        }
        case 'event': {
          if (t.length !== 3) throw new Fail('expected event <tick> <key>')
          const tick = int(t[1], 'tick', 0)
          if (!NAME.test(t[2])) throw new Fail(`invalid key ${t[2]}`)
          if (lastTick !== null && tick < lastTick) throw new Fail(`tick ${tick} is before tick ${lastTick}`)
          lastTick = tick
          seenEvent = true
          events.push({ tick, key: t[2] })
          break
        }
        default:
          throw new Fail(`unknown directive ${t[0]}`)
      }
    } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${i + 1}: ${e.message}`)
      throw e
    }
  }
  return { routes, events }
}

function run({ routes, events }) {
  const states = new Map() // `${policy}\0${key}` -> state
  const stateFor = (p, key, tick) => {
    const id = p.name + '\0' + key
    let s = states.get(id)
    if (!s) {
      s = p.kind === 'bucket' ? { scaled: p.capacity * p.per, last: tick } : { ticks: [] }
      states.set(id, s)
    }
    return s
  }
  const prefixes = [...routes.keys()]
  const out = []
  for (const { tick, key } of events) {
    let best = null
    for (const pre of prefixes) if (key.startsWith(pre) && (best === null || pre.length > best.length)) best = pre
    if (best === null) { out.push({ tick, key, denier: null }); continue }
    const route = routes.get(best)
    const sts = route.map((p) => {
      const s = stateFor(p, key, tick)
      if (p.kind === 'bucket') {
        const cap = p.capacity * p.per
        s.scaled += p.refill * (tick - s.last)
        if (s.scaled > cap) s.scaled = cap
        s.last = tick
      } else {
        const cut = tick - p.span
        s.ticks = s.ticks.filter((x) => x > cut)
      }
      return s
    })
    let denier = null
    for (let i = 0; i < route.length && denier === null; i++) {
      const p = route[i], s = sts[i]
      const ok = p.kind === 'bucket' ? s.scaled >= p.per : BigInt(s.ticks.length) < p.limit
      if (!ok) denier = p.name
    }
    if (denier === null) {
      route.forEach((p, i) => {
        if (p.kind === 'bucket') sts[i].scaled -= p.per
        else sts[i].ticks.push(tick)
      })
    }
    out.push({ tick, key, denier })
  }
  return out
}

let result
try {
  const parsed = parse(readFileSync(0, 'utf8'))
  result = run(parsed)
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}

let text = ''
if (mode === 'replay') {
  for (const r of result) text += `${r.tick} ${r.key} ${r.denier === null ? 'allow' : 'deny ' + r.denier}\n`
} else {
  const per = new Map()
  let a = 0, d = 0
  for (const r of result) {
    const c = per.get(r.key) || { a: 0, d: 0 }
    if (r.denier === null) { c.a++; a++ } else { c.d++; d++ }
    per.set(r.key, c)
  }
  for (const k of [...per.keys()].sort((x, y) => (x < y ? -1 : x > y ? 1 : 0))) text += `${k} allowed=${per.get(k).a} denied=${per.get(k).d}\n`
  text += `total allowed=${a} denied=${d}\n`
}
process.stdout.write(text)
EOF
