import { readFileSync } from 'node:fs'

const NAME = /^[A-Za-z0-9_.\/:-]+$/
const UINT = /^(0|[1-9][0-9]*)$/

class Fail extends Error {}

function parse(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let lastTick = null
  lines.forEach((raw, i) => {
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const f = line.split(/\s+/)
    const fail = (m) => { throw new Fail(`error: line ${i + 1}: ${m}`) }
    const num = (v, field, least) => {
      if (!UINT.test(v) || BigInt(v) < BigInt(least)) fail(`${field} must be an integer of at least ${least}`)
      return BigInt(v)
    }
    const d = f[0]
    if (!['bucket', 'window', 'route', 'event'].includes(d)) fail(`unknown directive ${d}`)
    if (d !== 'event' && events.length) fail('declarations must come before the first event')
    if (d === 'bucket') {
      if (f.length !== 5) fail('expected bucket <name> <capacity> <refill> <per>')
      if (!NAME.test(f[1])) fail(`invalid policy name ${f[1]}`)
      const capacity = num(f[2], 'capacity', 1)
      const refill = num(f[3], 'refill', 0)
      const per = num(f[4], 'per', 1)
      if (policies.has(f[1])) fail(`policy ${f[1]} is declared twice`)
      policies.set(f[1], { kind: 'bucket', name: f[1], capacity, refill, per })
    } else if (d === 'window') {
      if (f.length !== 4) fail('expected window <name> <limit> <span>')
      if (!NAME.test(f[1])) fail(`invalid policy name ${f[1]}`)
      const limit = num(f[2], 'limit', 0)
      const span = num(f[3], 'span', 1)
      if (policies.has(f[1])) fail(`policy ${f[1]} is declared twice`)
      policies.set(f[1], { kind: 'window', name: f[1], limit, span })
    } else if (d === 'route') {
      if (f.length < 3) fail('expected route <prefix> <policy>...')
      if (!NAME.test(f[1])) fail(`invalid route prefix ${f[1]}`)
      for (const p of f.slice(2)) if (!policies.has(p)) fail(`unknown policy ${p}`)
      if (routes.has(f[1])) fail(`prefix ${f[1]} is routed twice`)
      routes.set(f[1], f.slice(2).map((p) => policies.get(p)))
    } else {
      if (f.length !== 3) fail('expected event <tick> <key>')
      const tick = num(f[1], 'tick', 0)
      if (!NAME.test(f[2])) fail(`invalid key ${f[2]}`)
      if (lastTick !== null && tick < lastTick) fail(`tick ${tick} is before tick ${lastTick}`)
      lastTick = tick
      events.push({ tick, key: f[2] })
    }
  })
  return { routes, events }
}

function run(mode, text) {
  const { routes, events } = parse(text)
  const prefixes = [...routes.keys()]
  const states = new Map() // policy name + '\0' + key
  const stateOf = (p, key, tick) => {
    const id = p.name + '\0' + key
    let s = states.get(id)
    if (!s) {
      s = p.kind === 'bucket' ? { units: p.capacity * p.per, last: tick } : { ticks: [] }
      states.set(id, s)
    }
    return s
  }
  const out = []
  const per = new Map()
  let ta = 0, td = 0
  for (const { tick, key } of events) {
    let best = null
    for (const p of prefixes) if (key.startsWith(p) && (best === null || p.length > best.length)) best = p
    let denier = null
    if (best !== null) {
      const route = routes.get(best)
      const sts = route.map((p) => {
        const s = stateOf(p, key, tick)
        if (p.kind === 'bucket') {
          s.units += p.refill * (tick - s.last)
          const cap = p.capacity * p.per
          if (s.units > cap) s.units = cap
          s.last = tick
        } else {
          const cut = tick - p.span
          s.ticks = s.ticks.filter((t) => t > cut)
        }
        return s
      })
      for (let i = 0; i < route.length && !denier; i++) {
        const p = route[i], s = sts[i]
        const ok = p.kind === 'bucket' ? s.units >= p.per : BigInt(s.ticks.length) < p.limit
        if (!ok) denier = p.name
      }
      if (!denier) {
        route.forEach((p, i) => {
          if (p.kind === 'bucket') sts[i].units -= p.per
          else sts[i].ticks.push(tick)
        })
      }
    }
    if (!per.has(key)) per.set(key, [0, 0])
    per.get(key)[denier ? 1 : 0]++
    if (denier) td++; else ta++
    out.push(denier ? `${tick} ${key} deny ${denier}` : `${tick} ${key} allow`)
  }
