function diff(base, side) {
  const n = base.length, m = side.length
  const L = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(0))
  for (let i = n - 1; i >= 0; i--)
    for (let j = m - 1; j >= 0; j--)
      L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
  const changes = []
  let i = 0, j = 0, bs = 0, ss = 0
  const flush = () => {
    if (i > bs || j > ss) changes.push({ bs, be: i, ss, se: j })
  }
  while (i < n || j < m) {
    if (i < n && j < m && base[i] === side[j]) {
      flush(); i++; j++; bs = i; ss = j
    } else if (i < n && (j >= m || L[i + 1][j] >= L[i][j + 1])) i++
    else j++
  }
  flush()
  return changes
}

const eq = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])

export function merge(mine, base, theirs, mode) {
  const all = [
    ...diff(base, mine).map(c => ({ ...c, side: 0 })),
    ...diff(base, theirs).map(c => ({ ...c, side: 1 })),
  ].sort((a, b) => a.bs - b.bs || a.side - b.side)
  const out = []
  let conflict = false
  const regions = mode === 'regions'
  const emit = (...ls) => { if (!regions) out.push(...ls) }
  const stable = (from, to) => {
    if (to > from) { if (regions) out.push(`stable ${to - from}`); else out.push(...base.slice(from, to)) }
  }
  let pos = 0, k = 0
  while (k < all.length) {
    const rs = all[k].bs
    let re = all[k].be
    const group = [all[k++]]
    while (k < all.length && all[k].bs <= re) {
      re = Math.max(re, all[k].be)
      group.push(all[k++])
    }
    stable(pos, rs)
    pos = re
    const rep = [mine, theirs].map((doc, s) => {
      const cs = group.filter(c => c.side === s)
      if (!cs.length) return base.slice(rs, re)
      const minB = Math.min(...cs.map(c => c.bs)), minS = Math.min(...cs.map(c => c.ss))
      const maxB = Math.max(...cs.map(c => c.be)), maxS = Math.max(...cs.map(c => c.se))
