    else if (eq(m, b)) { res = t; label = 'theirs' }
    else if (eq(t, b)) { res = m; label = 'mine' }
    if (res) {
      if (regions) out.push(`${label} ${res.length}`)
      else out.push(...res)
    } else {
      conflict = true
      if (regions) out.push(`conflict mine=${m.length} base=${b.length} theirs=${t.length}`)
