lines.forEach((raw, i) => {
  const n = i + 1
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) return
  const w = line.split(/\s+/)
  if (w[0] === 'task') {
    if (w.length !== 3) fail(`error: line ${n}: expected task <name> <cost>`)
    if (!NAME.test(w[1])) fail(`error: line ${n}: invalid task name ${w[1]}`)
    if (!/^[0-9]+$/.test(w[2])) fail(`error: line ${n}: cost must be a non-negative integer`)
    if (cost.has(w[1])) fail(`error: line ${n}: task ${w[1]} is declared twice`)
    cost.set(w[1], BigInt(w[2]))
  } else if (w[0] === 'dep') {
    if (w.length < 3) fail(`error: line ${n}: expected dep <name> <dependency>...`)
    for (const name of w.slice(1)) {
      if (!NAME.test(name)) fail(`error: line ${n}: invalid task name ${name}`)
    }
    depLines.push(w.slice(1))
  } else {
    fail(`error: line ${n}: unknown directive ${w[0]}`)
  }
})

const deps = new Map()
for (const k of cost.keys()) deps.set(k, new Set())
for (const w of depLines) {
  for (const name of w) if (!cost.has(name)) fail(`error: unknown task ${name}`)
  for (const d of w.slice(1)) deps.get(w[0]).add(d)
}
const names = [...cost.keys()].sort()
const sortedDeps = new Map(names.map((k) => [k, [...deps.get(k)].sort()]))

// cycle detection
{
  const state = new Map()
  const stack = []
  const visit = (k) => {
    state.set(k, 1)
    stack.push(k)
    for (const d of sortedDeps.get(k)) {
      const s = state.get(d)
      if (s === 1) {
        const cyc = [...stack.slice(stack.indexOf(d)), d]
        fail('error: cycle: ' + cyc.join(' -> '), 3)
      }
      if (!s) visit(d)
    }
    stack.pop()
    state.set(k, 2)
  }
  for (const k of names) if (!state.get(k)) visit(k)
}

const start = new Map()
const finish = new Map()
const depth = new Map()
const prio = new Map()
const calc = (k) => {
  if (finish.has(k)) return
  let s = 0n
  let d = 0
  for (const x of sortedDeps.get(k)) {
    calc(x)
    if (finish.get(x) > s) s = finish.get(x)
    if (depth.get(x) + 1 > d) d = depth.get(x) + 1
  }
  start.set(k, s)
  finish.set(k, s + cost.get(k))
  depth.set(k, d)
}
names.forEach(calc)
const rev = new Map(names.map((k) => [k, []]))
for (const k of names) for (const d of sortedDeps.get(k)) rev.get(d).push(k)
const pr = (k) => {
  if (prio.has(k)) return prio.get(k)
  let m = 0n
  for (const x of rev.get(k)) if (pr(x) > m) m = pr(x)
  prio.set(k, m + cost.get(k))
  return prio.get(k)
}
names.forEach(pr)

let total = 0n
for (const k of names) if (finish.get(k) > total) total = finish.get(k)

const out = []
if (mode === 'waves') {
  const ws = []
  for (const k of names) (ws[depth.get(k)] ||= []).push(k)
  ws.forEach((w, i) => out.push(`wave ${i}: ${w.join(' ')}`))
  out.push(`total ${total}`)
} else if (mode === 'explain') {
  for (const k of names) out.push(`${k} start=${start.get(k)} finish=${finish.get(k)} depth=${depth.get(k)}`)
  out.push(`total ${total}`)
} else {
  const freeAt = new Array(workers).fill(0n)
  const runs = Array.from({ length: workers }, () => [])
  const fin = new Map()
  const pending = new Set(names)
  let t = 0n
  let makespan = 0n
  while (pending.size) {
    for (;;) {
      const wi = freeAt.findIndex((f) => f <= t)
      if (wi < 0) break
      let best = null
      for (const k of pending) {
        if (!sortedDeps.get(k).every((d) => fin.has(d) && fin.get(d) <= t)) continue
        if (best === null || prio.get(k) > prio.get(best) || (prio.get(k) === prio.get(best) && k < best)) best = k
      }
      if (best === null) break
      pending.delete(best)
      const f = t + cost.get(best)
      fin.set(best, f)
      freeAt[wi] = f
      runs[wi].push(`${best}@${t}-${f}`)
      if (f > makespan) makespan = f
    }
    if (!pending.size) break
    let next = null
    for (const f of freeAt) if (f > t && (next === null || f < next)) next = f
    if (next === null) break
    t = next
  }
  runs.forEach((r, i) => out.push(`worker ${i}:` + r.map((x) => ' ' + x).join('')))
  out.push(`makespan ${makespan}`)
}
process.stdout.write(out.join('\n') + '\n')
