if (names === null) fail('error: no candidates')

const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)
const total = ballots.reduce((s, b) => s + b.count, 0)
const continuing = new Set(names)
const history = []
const out = []
let winner = null

for (let round = 1; ; round++) {
  const counts = new Map([...continuing].map((c) => [c, 0]))
  let active = 0
  for (const b of ballots) {
    const c = b.prefs.find((p) => continuing.has(p))
    if (c !== undefined) {
      counts.set(c, counts.get(c) + b.count)
      active += b.count
    }
  }
  history.push(counts)
  const list = [...counts.entries()].sort((a, b) => b[1] - a[1] || cmp(a[0], b[0]))
  out.push(`round ${round}: ${list.map(([c, v]) => `${c}=${v}`).join(' ')} exhausted=${total - active}`)
  if (active === 0) break
  const top = list.find(([, v]) => v * 2 > active)
  if (top) {
    winner = top[0]
    break
  }
  let min = Math.min(...counts.values())
  let tied = [...counts].filter(([, v]) => v === min).map(([c]) => c)
  while (tied.length > 1) {
    let split = false
    for (const h of history) {
      const m = Math.min(...tied.map((c) => h.get(c)))
      const keep = tied.filter((c) => h.get(c) === m)
      if (keep.length < tied.length) {
        tied = keep
        split = true
        break
      }
    }
    if (!split) {
      tied = [tied.sort(cmp).pop()]
    }
  }
  continuing.delete(tied[0])
  out.push(`eliminated ${tied[0]}`)
}

const end = winner === null ? 'no winner' : `winner ${winner}`
if (mode === 'tally') process.stdout.write(`rounds ${history.length}\n${end}\n`)
else process.stdout.write(out.join('\n') + '\n' + end + '\n')
