    break
  }
  let cand = [...cont]
  const min = Math.min(...cand.map((c) => counts.get(c)))
  cand = cand.filter((c) => counts.get(c) === min)
  for (let r = 0; cand.length > 1 && r < history.length; r++) {
    const vs = cand.map((c) => history[r].get(c))
    const m = Math.min(...vs)
    if (vs.some((v) => v !== m)) {
