    r.authority = s.slice(i + 2, e)
    i = e
  }
  let e = i
  while (e < s.length && !'?#'.includes(s[e])) e++
  r.path = s.slice(i, e)
  i = e
  if (s[i] === '?') {
    e = i + 1
    while (e < s.length && s[e] !== '#') e++
    r.query = s.slice(i + 1, e)
    i = e
  }
  if (s[i] === '#') r.fragment = s.slice(i + 1)
  return r
}

export function splitAuthority(a) {
  let userinfo, rest = a
  const at = a.lastIndexOf('@')
  if (at >= 0) { userinfo = a.slice(0, at); rest = a.slice(at + 1) }
  const rb = rest.lastIndexOf(']')
  const colon = rest.indexOf(':', rb + 1)
  let host = rest, port
  if (colon >= 0) { host = rest.slice(0, colon); port = rest.slice(colon + 1) }
  return { userinfo, host, port }
}

