const cells = new Map()
for (let i = 0; i < lines.length; i++) {
  const s = lines[i].replace(/^[ \t]+/, '')
  if (s === '' || s[0] === '#') continue
  const m = /^([^ \t]*)[ \t]*([\s\S]*)$/.exec(s)
  const word = m[1]
  const a = parseAddr(word)
  if (!a) {
    process.stderr.write(`error: line ${i + 1}: invalid cell address ${word}\n`)
    process.exit(2)
  }
  const k = key(a.c, a.r)
  if (cells.has(k)) {
    process.stderr.write(`error: line ${i + 1}: cell ${word} is declared twice\n`)
    process.exit(2)
  }
  cells.set(k, { c: a.c, r: a.r, content: m[2] })
}

// ---- formula parser
const ARITY = { SUM: 'n', MIN: 'n', MAX: 'n', COUNT: 'n', AVG: 'n', ABS: 1, IF: 3 }

function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const ch = s[i]
    if (ch === ' ' || ch === '\t') { i++; continue }
    let m
    if ((m = /^\d+(\.\d+)?/.exec(s.slice(i)))) { toks.push({ k: 'num', v: m[0] }); i += m[0].length; continue }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) { toks.push({ k: 'word', v: m[0] }); i += m[0].length; continue }
    const two = s.slice(i, i + 2)
    if (two === '<>' || two === '<=' || two === '>=') { toks.push({ k: 'op', v: two }); i += 2; continue }
    if ('^*/+-=<>():,'.includes(ch)) { toks.push({ k: 'op', v: ch }); i++; continue }
    return null
  }
  return toks
}

// returns {ast, bad, deps} or null on grammar failure
function parseFormula(body) {
  const toks = tokenize(body)
  if (!toks) return null
  let p = 0
  let bad = false
  const deps = []
  const fail = () => { throw new Error('g') }
  const peek = () => toks[p]
  const isOp = (v) => p < toks.length && toks[p].k === 'op' && toks[p].v === v

  function rangeNode() {
    const w1 = toks[p++].v
    p++ // ':'
    if (p >= toks.length || toks[p].k !== 'word') fail()
    const w2 = toks[p++].v
    const a = parseAddr(w1), b = parseAddr(w2)
    if (a && b) {
      for (let c = Math.min(a.c, b.c); c <= Math.max(a.c, b.c); c++)
        for (let r = Math.min(a.r, b.r); r <= Math.max(a.r, b.r); r++) deps.push({ c, r })
    }
    return { n: 'range', a, b }
  }
  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].k === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { n: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) { const op = toks[p++].v; l = { n: 'bin', op, l, r: mul() } }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) { const op = toks[p++].v; l = { n: 'bin', op, l, r: pow() } }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { n: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) { const op = toks[p++].v; return { n: 'un', op, e: unary() } }
    return primary()
  }
  function primary() {
    const t = peek()
    if (!t) fail()
    if (t.k === 'num') { p++; return { n: 'num', v: Number(t.v) } }
    if (t.k === 'op') {
      if (t.v === '(') {
        p++
        const e = cmp()
        if (!isOp(')')) fail()
        p++
        return e
      }
      fail()
    }
    const next = toks[p + 1]
    if (next && next.k === 'op' && next.v === '(') {
      const name = t.v.toUpperCase()
      p += 2
      const args = []
      if (!isOp(')')) {
        for (;;) {
          args.push(arg())
          if (isOp(',')) { p++; continue }
          break
        }
      }
      if (!isOp(')')) fail()
      p++
      if (typeof ARITY[name] === 'number') {
        for (const a of args) if (a.n === 'range') bad = true
      }
      return { n: 'call', name, args }
    }
    if (next && next.k === 'op' && next.v === ':') {
      const r = rangeNode()
      bad = true
      return r
    }
    p++
    const up = t.v.toUpperCase()
    if (up === 'TRUE') return { n: 'bool', v: true }
    if (up === 'FALSE') return { n: 'bool', v: false }
    const a = parseAddr(t.v)
    if (a) deps.push(a)
    return { n: 'ref', a }
  }
  function arg() {
    const t = peek()
    const next = toks[p + 1]
    if (t && t.k === 'word' && next && next.k === 'op' && next.v === ':') return rangeNode()
    return cmp()
  }
  try {
    const ast = cmp()
    if (p !== toks.length) return null
    return { ast, bad, deps }
  } catch (e) {
    if (e.message === 'g') return null
    throw e
  }
}

// ---- evaluation
const compiled = new Map()
function compile(cell) {
  if (compiled.has(cell)) return compiled.get(cell)
  let r = null
  if (cell.content[0] === '=') r = parseFormula(cell.content.slice(1))
  compiled.set(cell, r)
  return r
}

const memo = new Map()
const active = new Set()

function cellValue(k) {
  if (memo.has(k)) return memo.get(k)
  const cell = cells.get(k)
  if (!cell) return num(0)
  if (active.has(k)) return err('#CYCLE!')
  active.add(k)
  let v
  const content = cell.content
  if (content[0] === '=') {
    const f = compile(cell)
    if (!f || f.bad) v = err('#ERR!')
    else v = evalNode(f.ast)
  } else if (content === '') v = num(0)
  else if (NUM_RE.test(content)) v = num(Number(content))
  else if (ERRS.includes(content)) v = err(content)
  else v = { t: 'text', s: content }
  active.delete(k)
  memo.set(k, v)
  return v
}

function toNum(v) {
  if (v.t === 'num') return v
  if (v.t === 'bool') return num(v.b ? 1 : 0)
  if (v.t === 'text') return err('#VALUE!')
  return v
}
const fin = (n) => (Number.isFinite(n) ? num(n) : err('#DIV/0!'))

function rank(v) { return v.t === 'num' ? 0 : v.t === 'text' ? 1 : 2 }
function cmpVals(a, b) {
  const ra = rank(a), rb = rank(b)
  if (ra !== rb) return ra < rb ? -1 : 1
  if (ra === 0) return a.n < b.n ? -1 : a.n > b.n ? 1 : 0
  if (ra === 2) return a.b === b.b ? 0 : a.b ? 1 : -1
  const x = Array.from(a.s, (c) => c.codePointAt(0)), y = Array.from(b.s, (c) => c.codePointAt(0))
  for (let i = 0; i < Math.min(x.length, y.length); i++) if (x[i] !== y[i]) return x[i] < y[i] ? -1 : 1
  return x.length === y.length ? 0 : x.length < y.length ? -1 : 1
}

function expandArgs(args) {
  const out = []
  for (const a of args) {
    if (a.n === 'range') {
      if (!a.a || !a.b) { out.push(err('#REF!')); continue }
      for (let c = Math.min(a.a.c, a.b.c); c <= Math.max(a.a.c, a.b.c); c++)
        for (let r = Math.min(a.a.r, a.b.r); r <= Math.max(a.a.r, a.b.r); r++) out.push(cellValue(key(c, r)))
    } else out.push(evalNode(a))
  }
  return out
}

function evalNode(n) {
  switch (n.n) {
    case 'num': return num(n.v)
    case 'bool': return { t: 'bool', b: n.v }
    case 'ref': return n.a ? cellValue(key(n.a.c, n.a.r)) : err('#REF!')
    case 'range': return err('#ERR!')
    case 'un': {
      const v = toNum(evalNode(n.e))
      if (v.t === 'err') return v
      return num(n.op === '-' ? -v.n : v.n)
    }
    case 'bin': {
      const l = evalNode(n.l)
      if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
        if (l.t === 'err') return l
        const r = evalNode(n.r)
        if (r.t === 'err') return r
        const c = cmpVals(l, r)
        const b = { '=': c === 0, '<>': c !== 0, '<': c < 0, '<=': c <= 0, '>': c > 0, '>=': c >= 0 }[n.op]
        return { t: 'bool', b }
      }
      const a = toNum(l)
      if (a.t === 'err') return a
      const b = toNum(evalNode(n.r))
      if (b.t === 'err') return b
      switch (n.op) {
        case '+': return fin(a.n + b.n)
        case '-': return fin(a.n - b.n)
        case '*': return fin(a.n * b.n)
        case '/': return b.n === 0 ? err('#DIV/0!') : fin(a.n / b.n)
        default: return fin(Math.pow(a.n, b.n))
      }
    }
    default: return evalCall(n)
  }
}

function evalCall(n) {
  const ar = ARITY[n.name]
  if (ar === undefined) return err('#NAME?')
  if (ar === 'n' ? n.args.length < 1 : n.args.length !== ar) return err('#ERR!')
  if (n.name === 'IF') {
    const c = evalNode(n.args[0])
    if (c.t === 'err') return c
    let truth
    if (c.t === 'bool') truth = c.b
    else if (c.t === 'num') truth = c.n !== 0
    else return err('#VALUE!')
    return evalNode(n.args[truth ? 1 : 2])
  }
  const vals = expandArgs(n.args)
  const e = vals.find((v) => v.t === 'err')
  if (e) return e
  if (n.name === 'COUNT') return num(vals.filter((v) => v.t === 'num').length)
  const nums = []
  for (const v of vals) {
    const x = toNum(v)
    if (x.t === 'err') return x
    nums.push(x.n)
  }
  switch (n.name) {
    case 'ABS': return num(Math.abs(nums[0]))
    case 'SUM': return fin(nums.reduce((a, b) => a + b, 0))
    case 'MIN': return num(Math.min(...nums))
    case 'MAX': return num(Math.max(...nums))
    default: return fin(nums.reduce((a, b) => a + b, 0) / nums.length)
  }
}

function fmt(v) {
  switch (v.t) {
    case 'num': return String(Number(v.n.toPrecision(10)))
    case 'text': return v.s
    case 'bool': return v.b ? 'TRUE' : 'FALSE'
    default: return v.e
  }
}

const sorted = [...cells.values()].sort((a, b) => a.c - b.c || a.r - b.r)
let out = ''
for (const cell of sorted) {
  const name = colName(cell.c) + cell.r
  if (mode === 'values') {
    out += `${name}=${fmt(cellValue(key(cell.c, cell.r)))}\n`
  } else {
    let list = []
    if (cell.content[0] === '=') {
      const f = compile(cell)
      if (f) {
        const seen = new Map()
        for (const d of f.deps) seen.set(key(d.c, d.r), d)
        list = [...seen.values()].sort((a, b) => a.c - b.c || a.r - b.r)
      }
    }
    out += `${name}:${list.map((d) => ' ' + colName(d.c) + d.r).join('')}\n`
  }
}
process.stdout.write(out)
"}

