import { readFileSync } from 'node:fs'

const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'

function fail(msg, code = 2) {
  process.stderr.write(msg + '\n')
  process.exit(code)
}

const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

const args = process.argv.slice(2)
let workers = 0
if (args.length === 1 && (args[0] === 'waves' || args[0] === 'explain')) {
  // ok
} else if (args.length === 2 && args[0] === 'pack') {
  if (!/^[1-9][0-9]*$/.test(args[1])) fail('error: workers must be a positive integer')
  workers = Number(args[1])
} else fail(USAGE)
const mode = args[0]

let input = ''
try { input = readFileSync(0, 'utf8') } catch { input = '' }
const lines = input.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const costs = new Map()
const deps = new Map()
const depLines = []
const NAME = /^[A-Za-z0-9_.-]+$/
for (let i = 0; i < lines.length; i++) {
  const line = lines[i].trim()
  if (line === '' || line.startsWith('#')) continue
  const w = line.split(/\s+/)
  const n = i + 1
  if (w[0] === 'task') {
    if (w.length !== 3) fail(`error: line ${n}: expected task <name> <cost>`)
    if (!NAME.test(w[1])) fail(`error: line ${n}: invalid task name ${w[1]}`)
    if (!/^[0-9]+$/.test(w[2])) fail(`error: line ${n}: cost must be a non-negative integer`)
    if (costs.has(w[1])) fail(`error: line ${n}: task ${w[1]} is declared twice`)
    costs.set(w[1], BigInt(w[2]))
  } else if (w[0] === 'dep') {
    if (w.length < 3) fail(`error: line ${n}: expected dep <name> <dependency>...`)
    depLines.push(w.slice(1))
  } else fail(`error: line ${n}: unknown directive ${w[0]}`)
}
for (const name of costs.keys()) deps.set(name, new Set())
for (const w of depLines) {
  for (const x of w) if (!costs.has(x)) fail(`error: unknown task ${x}`)
  for (const d of w.slice(1)) deps.get(w[0]).add(d)
}
const names = [...costs.keys()].sort(cmp)
const dl = new Map(names.map((k) => [k, [...deps.get(k)].sort(cmp)]))

// cycle detection
{
  const state = new Map()
  const stack = []
  const visit = (u) => {
    state.set(u, 1)
    stack.push(u)
    for (const v of dl.get(u)) {
      const s = state.get(v)
      if (s === 1) {
        const cyc = stack.slice(stack.indexOf(v)).concat(v)
        fail('error: cycle: ' + cyc.join(' -> '), 3)
      }
      if (!s) visit(v)
    }
    stack.pop()
    state.set(u, 2)
  }
  for (const k of names) if (!state.get(k)) visit(k)
}

const start = new Map()
const finish = new Map()
const depth = new Map()
const calc = (u) => {
  if (finish.has(u)) return
  let s = 0n
  let d = 0
  for (const v of dl.get(u)) {
    calc(v)
    if (finish.get(v) > s) s = finish.get(v)
    if (depth.get(v) + 1 > d) d = depth.get(v) + 1
  }
  start.set(u, s)
  finish.set(u, s + costs.get(u))
  depth.set(u, d)
}
for (const k of names) calc(k)
let total = 0n
for (const k of names) if (finish.get(k) > total) total = finish.get(k)

let out = ''
if (mode === 'waves') {
  const waves = []
  for (const k of names) (waves[depth.get(k)] ??= []).push(k)
  waves.forEach((w, i) => { out += `wave ${i}: ${w.join(' ')}\n` })
  out += `total ${total}\n`
} else if (mode === 'explain') {
  for (const k of names) out += `${k} start=${start.get(k)} finish=${finish.get(k)} depth=${depth.get(k)}\n`
  out += `total ${total}\n`
} else {
  const rev = new Map(names.map((k) => [k, []]))
  for (const k of names) for (const d of dl.get(k)) rev.get(d).push(k)
  const prio = new Map()
  const pr = (u) => {
    if (prio.has(u)) return prio.get(u)
    let m = 0n
    for (const v of rev.get(u)) { const p = pr(v); if (p > m) m = p }
    prio.set(u, m + costs.get(u))
    return m + costs.get(u)
  }
  for (const k of names) pr(k)
  const order = names.slice().sort((a, b) => (prio.get(a) > prio.get(b) ? -1 : prio.get(a) < prio.get(b) ? 1 : cmp(a, b)))
  const done = new Map() // name -> finish
  const free = Array(workers).fill(0n)
  const ran = Array.from({ length: workers }, () => [])
  let t = 0n
  let remaining = names.length
  let makespan = 0n
  while (remaining > 0) {
    for (;;) {
      const w = free.findIndex((f) => f <= t)
      if (w < 0) break
      const task = order.find((k) => !done.has(k) && dl.get(k).every((d) => done.has(d) && done.get(d) <= t))
      if (task === undefined) break
      const f = t + costs.get(task)
      done.set(task, f)
      free[w] = f
      ran[w].push(`${task}@${t}-${f}`)
      if (f > makespan) makespan = f
      remaining--
    }
    if (remaining === 0) break
    let next = null
    for (const f of free) if (f > t && (next === null || f < next)) next = f
    if (next === null) break
    t = next
  }
  ran.forEach((r, i) => { out += `worker ${i}:${r.map((x) => ' ' + x).join('')}\n` })
  out += `makespan ${makespan}\n`
}
process.stdout.write(out)
EOF
