    state.set(u, 1)
    stack.push(u)
    for (const v of dl.get(u)) {
      const s = state.get(v)
      if (s === 1) {
        const cyc = stack.slice(stack.indexOf(v)).concat(v)
        fail('error: cycle: ' + cyc.join(' -> '), 3)
      }
      if (!s) visit(v)
    }
    stack.pop()
    state.set(u, 2)
  }
  for (const k of names) if (!state.get(k)) visit(k)
}

const start = new Map()
const finish = new Map()
const depth = new Map()
const calc = (u) => {
  if (finish.has(u)) return
  let s = 0n
  let d = 0
  for (const v of dl.get(u)) {
    calc(v)
    if (finish.get(v) > s) s = finish.get(v)
    if (depth.get(v) + 1 > d) d = depth.get(v) + 1
  }
  start.set(u, s)
  finish.set(u, s + costs.get(u))
  depth.set(u, d)
}
for (const k of names) calc(k)
let total = 0n
for (const k of names) if (finish.get(k) > total) total = finish.get(k)

let out = ''
if (mode === 'waves') {
  const waves = []
  for (const k of names) (waves[depth.get(k)] ??= []).push(k)
  waves.forEach((w, i) => { out += `wave ${i}: ${w.join(' ')}\n` })
  out += `total ${total}\n`
