  const ran = Array.from({ length: workers }, () => [])
  let t = 0n
  let remaining = names.length
  let makespan = 0n
  while (remaining > 0) {
    for (;;) {
      const w = free.findIndex((f) => f <= t)
      if (w < 0) break
      const task = order.find((k) => !done.has(k) && dl.get(k).every((d) => done.has(d) && done.get(d) <= t))
