      const f = t + costs.get(task)
      done.set(task, f)
      free[w] = f
      ran[w].push(`${task}@${t}-${f}`)
      if (f > makespan) makespan = f
      remaining--
    }
    if (remaining === 0) break
    let next = null
    for (const f of free) if (f > t && (next === null || f < next)) next = f
    if (next === null) break
    t = next
  }
  ran.forEach((r, i) => { out += `worker ${i}:${r.map((x) => ' ' + x).join('')}\n` })
  out += `makespan ${makespan}\n`
}
process.stdout.write(out)
