{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */
import { readFileSync } from 'node:fs'
import { parse } from './parser.js'
import { toJson, toKeys } from './output.js'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'json' && mode !== 'keys') {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}

let root
try {
  root = parse(readFileSync(0, 'utf8'))
} catch (e) {
  if (e && e.isConfigError) {
    process.stderr.write(`error: ${e.message}\n`)
    process.exit(2)
  }
  throw e
}
process.stdout.write(mode === 'json' ? toJson(root) : toKeys(root))
"}

{"file_path":"src/output.js","content":"function cmp(a, b) {
  const x = Array.from(a)
  const y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d !== 0) return d
  }
  return x.length - y.length
}

function sortedKeys(node) {
  return [...node.m.keys()].sort(cmp)
}

function scalarJson(node) {
  switch (node.t) {
    case 'string': return JSON.stringify(node.v)
    case 'integer': return node.v
    case 'float': return JSON.stringify(node.v)
    default: return String(node.v)
  }
}

function render(node, indent) {
  const pad = '  '.repeat(indent + 1)
  const end = '  '.repeat(indent)
  if (node.t === 'table') {
    const keys = sortedKeys(node)
    if (!keys.length) return '{}'
    const parts = keys.map((k) => `${pad}${JSON.stringify(k)}: ${render(node.m.get(k), indent + 1)}`)
    return `{\n${parts.join(',\n')}\n${end}}`
  }
  if (node.t === 'array') {
    if (!node.items.length) return '[]'
    const parts = node.items.map((n) => pad + render(n, indent + 1))
    return `[\n${parts.join(',\n')}\n${end}]`
  }
  return scalarJson(node)
}

export function toJson(root) {
  return render(root, 0) + '\n'
}

export function toKeys(root) {
  const lines = []
  const walk = (node, path) => {
    if (node.t === 'table') {
      for (const k of sortedKeys(node)) {
        const p = path === '' ? k : `${path}.${k}`
        const c = node.m.get(k)
        lines.push(`${p} ${c.t}`)
        walk(c, p)
      }
    } else if (node.t === 'array') {
      node.items.forEach((c, i) => {
        const p = `${path}[${i}]`
        lines.push(`${p} ${c.t}`)
        walk(c, p)
      })
    }
  }
  walk(root, '')
  return lines.length ? lines.join('\n') + '\n' : ''
}
"}

{"file_path":"src/parser.js","content":"function fail(msg) {
  const e = new Error(msg)
  e.isConfigError = true
  throw e
}

const newTable = () => ({ t: 'table', m: new Map(), made: false })
const isWs = (c) => c === ' ' || c === '\t'
const isNameChar = (c) => c !== undefined && /^[A-Za-z0-9_-]$/.test(c)
const isStop = (c) => c === undefined || c === '#' || c === ';'

const INT = /^[+-]?\d+(_\d+)*$/
const FLOAT = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/

class Line {
  constructor(s) {
    this.s = s
    this.i = 0
  }
  get c() {
    return this.s[this.i]
  }
  ws() {
    while (isWs(this.s[this.i])) this.i++
  }
  atEnd() {
    this.ws()
    return isStop(this.c)
  }

  quoted() {
    const q = this.c
    this.i++
    let out = ''
    for (;;) {
      const c = this.c
      if (c === undefined) fail('unterminated string')
      this.i++
      if (c === q) return out
      if (q === '"' && c === '\\') {
        const e = this.c
        if (e === undefined) fail('unterminated string')
        this.i++
        if (e === '"') out += '"'
        else if (e === '\\') out += '\\'
        else if (e === 'n') out += '\n'
        else if (e === 't') out += '\t'
        else if (e === 'r') out += '\r'
        else if (e === '0') out += '\0'
        else if (e === 'u') {
          const h = this.s.slice(this.i, this.i + 4)
          if (!/^[0-9a-fA-F]{4}$/.test(h)) fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(h, 16))
          this.i += 4
        } else {
          const cp = String.fromCodePoint(this.s.codePointAt(this.i - 1))
          fail(`invalid escape \\${cp}`)
        }
      } else out += c
    }
  }

  name() {
    this.ws()
    const c = this.c
    if (c === '"' || c === "'") return this.quoted()
    const st = this.i
    while (isNameChar(this.c)) this.i++
    if (st === this.i) fail('expected a name')
    return this.s.slice(st, this.i)
  }

  dotted() {
    const names = [this.name()]
    for (;;) {
      const save = this.i
      this.ws()
      if (this.c === '.') {
        this.i++
        names.push(this.name())
      } else {
        this.i = save
        return names
      }
    }
  }

  value(path) {
    this.ws()
    const c = this.c
    if (isStop(c) || c === ',' || c === ']' || c === '}') fail('expected a value')
    if (c === '"' || c === "'") return { t: 'string', v: this.quoted() }
    if (c === '[') return this.array(path)
    if (c === '{') return this.inline(path)
    const st = this.i
    while (this.c !== undefined && !isWs(this.c) && this.c !== ',' && this.c !== ']' && this.c !== '}') this.i++
    const w = this.s.slice(st, this.i)
    if (w === 'true') return { t: 'boolean', v: true }
    if (w === 'false') return { t: 'boolean', v: false }
    if (INT.test(w)) return { t: 'integer', v: BigInt(w.replace(/_/g, '')).toString() }
    if (FLOAT.test(w)) return { t: 'float', v: Number(w.replace(/_/g, '')) }
    fail(`invalid value ${w}`)
  }

  array(path) {
    this.i++
    const items = []
    for (;;) {
      if (this.atEnd()) fail('unterminated array')
      if (this.c === ']') {
        this.i++
        return { t: 'array', items, aot: false }
      }
      items.push(this.value(path))
      if (this.atEnd()) fail('unterminated array')
      if (this.c === ',') this.i++
      else if (this.c === ']') {
        this.i++
        return { t: 'array', items, aot: false }
      } else fail('unterminated array')
    }
  }

  inline(path) {
    this.i++
    const tbl = newTable()
    if (this.atEnd()) fail('unterminated inline table')
    if (this.c === '}') {
      this.i++
      return tbl
    }
    for (;;) {
      this.ws()
      if (this.c === undefined) fail('unterminated inline table')
      const names = this.dotted()
      this.ws()
      if (this.c !== '=') fail('expected = in an inline table')
      this.i++
      const v = this.value([...path, ...names])
      setKey(tbl, path, names, v)
      if (this.atEnd()) fail('unterminated inline table')
      if (this.c === ',') this.i++
      else if (this.c === '}') {
        this.i++
        return tbl
      } else fail('unterminated inline table')
    }
  }
}

function setKey(tbl, base, names, value) {
  let cur = tbl
  for (let k = 0; k < names.length - 1; k++) {
    const n = names[k]
    let c = cur.m.get(n)
    if (c === undefined) {
      c = newTable()
      cur.m.set(n, c)
    } else if (c.t === 'array' && c.aot) c = c.items[c.items.length - 1]
    else if (c.t !== 'table') fail(`${[...base, ...names.slice(0, k + 1)].join('.')} is not a table`)
    cur = c
  }
  const last = names[names.length - 1]
  if (cur.m.has(last)) fail(`key ${[...base, ...names].join('.')} is defined twice`)
  cur.m.set(last, value)
}

function walkHeader(root, names) {
  let cur = root
  for (let k = 0; k < names.length - 1; k++) {
    const n = names[k]
    let c = cur.m.get(n)
    if (c === undefined) {
      c = newTable()
      cur.m.set(n, c)
    } else if (c.t === 'array' && c.aot) c = c.items[c.items.length - 1]
    else if (c.t !== 'table') fail(`${names.slice(0, k + 1).join('.')} is not a table`)
    cur = c
  }
  return cur
}

export function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let cur = root
  let curPath = []
  for (let ln = 0; ln < lines.length; ln++) {
    try {
      const L = new Line(lines[ln])
      L.ws()
      if (isStop(L.c) && (L.c === undefined || L.c === '#' || L.c === ';')) continue
      if (L.c === '[') {
        const dbl = L.s[L.i + 1] === '['
        L.i += dbl ? 2 : 1
        const names = L.dotted()
        L.ws()
        for (let k = 0; k < (dbl ? 2 : 1); k++) {
          if (L.c !== ']') fail('unterminated table header')
          L.i++
        }
        if (!L.atEnd()) fail('trailing text after a table header')
        const parent = walkHeader(root, names)
        const last = names[names.length - 1]
        const ex = parent.m.get(last)
        const p = names.join('.')
        if (dbl) {
          if (ex === undefined) {
            const a = { t: 'array', items: [], aot: true }
            parent.m.set(last, a)
            cur = newTable()
            a.items.push(cur)
          } else if (ex.t === 'array' && ex.aot) {
            cur = newTable()
            ex.items.push(cur)
          } else fail(`${p} is not an array of tables`)
          cur.made = true
        } else {
          if (ex === undefined) {
            cur = newTable()
            parent.m.set(last, cur)
          } else if (ex.t === 'table') {
            if (ex.made) fail(`table ${p} is defined twice`)
            cur = ex
          } else fail(`${p} is not a table`)
          cur.made = true
        }
        curPath = names
      } else {
        const names = L.dotted()
        L.ws()
        if (L.c !== '=') fail('expected key = value')
        L.i++
        const v = L.value([...curPath, ...names])
        if (!L.atEnd()) fail('trailing text after a value')
        setKey(cur, curPath, names, v)
      }
    } catch (e) {
      if (e && e.isConfigError) e.message = `line ${ln + 1}: ${e.message}`
      throw e
    }
  }
  return root
}
"}

